372	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
373	func (s *Store) persist(st *persistedState) error {
374		data, err := json.MarshalIndent(st, "", "  ")
375		if err != nil {
376			return err
377		}
378		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
379		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
380		if err != nil {
381			return err
382		}
383		if _, err := f.Write(data); err != nil {
384			f.Close()
385			return err
386		}
387		if err := f.Sync(); err != nil {
388			f.Close()
389			return err
390		}
391		if err := f.Close(); err != nil {
392			return err
393		}
394		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
395			return err
396		}
397		if d, err := os.Open(s.dir); err == nil {
398			_ = d.Sync()
399			_ = d.Close()
400		}
401		return nil
402	}
403	
404	func cloneState(st *persistedState) (*persistedState, error) {
405		data, err := json.Marshal(st)
406		if err != nil {
407			return nil, err
408		}
409		var out persistedState
410		if err := json.Unmarshal(data, &out); err != nil {
411			return nil, err
412		}
413		if out.Requests == nil {
414			out.Requests = map[string]*requestRecord{}
415		}
416		return &out, nil
417	}
418	
419	// write 是所有写入操作的统一入口：
420	//   - reqNo 为空直接报错；
421	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
422	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
423	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
424	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
425	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
426		if reqNo == "" {
427			return errors.New("请求编号不能为空")
428		}
429		s.mu.Lock()
430		defer s.mu.Unlock()
431		if err := s.lockExclusive(); err != nil {
432			return err
433		}
434		defer s.unlock()
435	
436		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
437		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
438		if err := s.load(); err != nil {
439			return err
440		}
441	
442		payloadRaw, err := json.Marshal(payload)
443		if err != nil {
444			return err
445		}
446		payloadStr := string(payloadRaw)
447	
448		if req, ok := s.state.Requests[reqNo]; ok {
449			if req.Op != op || req.Payload != payloadStr {
450				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
451					ErrRequestConflict, reqNo, req.Op, op)
452			}
453			if err := json.Unmarshal(req.Result, out); err != nil {
454				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
455			}
456			return nil
457		}
458	
459		clone, err := cloneState(s.state)
460		if err != nil {
461			return err
462		}
463		result, err := apply(clone)
464		if err != nil {
465			return err
466		}
467		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
468		if err := s.persist(clone); err != nil {
469			return fmt.Errorf("保存台账失败: %w", err)
470		}
471		s.state = clone
472		if err := json.Unmarshal(result, out); err != nil {
473			return fmt.Errorf("解析请求结果失败: %w", err)
474		}
475		return nil
476	}
477	
478	// read 在共享锁下读取当前状态。
479	func (s *Store) read(fn func(*persistedState) error) error {
480		s.mu.Lock()
481		defer s.mu.Unlock()
482		if err := s.lockShared(); err != nil {
483			return err
484		}
485		defer s.unlock()
486		if err := s.load(); err != nil {
487			return err
488		}
489		return fn(s.state)
490	}
