func registerTwoRecipeVersions(t *testing.T, s *Store) {
	t.Helper()
	if _, err := s.RegisterRecipe("recipe-v1", "R1", "v1", "配方初版", []MaterialInput{
		{MaterialNo: "M1", Grams: "100"},
