		t.Fatalf("物料 %q 核对应为 应投=%s 实投=%s 差额=%s，得到 应投=%s 实投=%s 差额=%s",
			mat, req, act, diff, m.RequiredGrams, m.ActualGrams, m.DifferenceGrams)
	}
}

